svg.script:
(() => {
  const root = document.documentElement;
  const hitCells = [...root.querySelectorAll('.hit-cell')];
  const axes = [
    root.getElementById('axis-a'),
    root.getElementById('axis-b'),
    root.getElementById('axis-c')
  ];
  let lockedId = null;
  let activeId = null;

  const byId = new Map(hitCells.map(el => [el.dataset.id, el]));

  function n(el, key) { return Number(el.dataset[key]); }

  function setAxis(line, members) {
    let bestA = members[0], bestB = members[0], bestD2 = -1;
    for (let i = 0; i < members.length; i++) {
      for (let j = i + 1; j < members.length; j++) {
        const dx = n(members[j], 'x') - n(members[i], 'x');
        const dy = n(members[j], 'y') - n(members[i], 'y');
        const d2 = dx*dx + dy*dy;
        if (d2 > bestD2) { bestD2 = d2; bestA = members[i]; bestB = members[j]; }
      }
    }
    let x1 = n(bestA, 'x'), y1 = n(bestA, 'y');
    let x2 = n(bestB, 'x'), y2 = n(bestB, 'y');
    let dx = x2 - x1, dy = y2 - y1;
    const len = Math.hypot(dx, dy) || 1;
    dx /= len; dy /= len;
    const extend = 47.52;
    x1 -= dx * extend; y1 -= dy * extend;
    x2 += dx * extend; y2 += dy * extend;
    line.setAttribute('x1', x1.toFixed(2));
    line.setAttribute('y1', y1.toFixed(2));
    line.setAttribute('x2', x2.toFixed(2));
    line.setAttribute('y2', y2.toFixed(2));
    line.classList.add('on');
  }

  function clearVisuals() {
    root.querySelectorAll('.cell-wash.on').forEach(el => el.classList.remove('on'));
    root.querySelectorAll('.cell-outline.selected').forEach(el => el.classList.remove('selected'));
    axes.forEach(a => a.classList.remove('on'));
    activeId = null;
  }

  function show(cell) {
    if (!cell) return;
    clearVisuals();
    activeId = cell.dataset.id;
    const q = cell.dataset.q, r = cell.dataset.r, s = cell.dataset.s;
    const aMembers = hitCells.filter(c => c.dataset.r === r); // horizontal
    const bMembers = hitCells.filter(c => c.dataset.q === q); // down-right
    const cMembers = hitCells.filter(c => c.dataset.s === s); // up-right

    aMembers.forEach(c => root.getElementById(c.dataset.id + '_a').classList.add('on'));
    bMembers.forEach(c => root.getElementById(c.dataset.id + '_b').classList.add('on'));
    cMembers.forEach(c => root.getElementById(c.dataset.id + '_c').classList.add('on'));

    root.getElementById(cell.dataset.id + '_outline').classList.add('selected');
    setAxis(axes[0], aMembers);
    setAxis(axes[1], bMembers);
    setAxis(axes[2], cMembers);
  }

  function unlockAndClear() {
    lockedId = null;
    clearVisuals();
  }

  hitCells.forEach(cell => {
    cell.addEventListener('pointerenter', e => {
      if (e.pointerType === 'mouse' && lockedId === null) show(cell);
    });
    cell.addEventListener('pointerleave', e => {
      if (e.pointerType === 'mouse' && lockedId === null && activeId === cell.dataset.id) clearVisuals();
    });
    cell.addEventListener('click', e => {
      e.stopPropagation();
      if (lockedId === cell.dataset.id) {
        unlockAndClear();
      } else {
        lockedId = cell.dataset.id;
        show(cell);
      }
    });
    cell.addEventListener('focus', () => {
      if (lockedId === null) show(cell);
    });
    cell.addEventListener('blur', () => {
      if (lockedId === null && activeId === cell.dataset.id) clearVisuals();
    });
    cell.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        if (lockedId === cell.dataset.id) unlockAndClear();
        else { lockedId = cell.dataset.id; show(cell); }
      } else if (e.key === 'Escape') {
        unlockAndClear();
        cell.blur();
      }
    });
  });

  root.addEventListener('click', () => unlockAndClear());
  root.addEventListener('keydown', e => { if (e.key === 'Escape') unlockAndClear(); });
})();
